// Flatten the Error Trigger payload. A failed run sends `execution`;
// a trigger that could not start sends `trigger` instead.
const d = $('On any workflow error').first().json;
const e = d.execution ?? d.trigger ?? {};
const wf = d.workflow ?? {};

return [{ json: {
  workflow_id: wf.id ?? 'unknown',
  workflow_name: wf.name ?? 'unknown',
  execution_id: String(e.id ?? 'none'),
  execution_url: e.url ?? `${$('Config').first().json.config.editor_base_url}/workflow/${wf.id}/executions/${e.id}`,
  node: e.lastNodeExecuted ?? e.error?.node?.name ?? 'unknown',
  error: e.error?.message ?? e.error?.description ?? 'unknown error',
  payload: d,
} }];
